  input      [N-1:0]           eligible,
  input      [N*PRIO_BITS-1:0] prio_flat,
  output reg                   best_valid,
  output reg [$clog2(N)-1:0]   best_idx,
  output reg [PRIO_BITS-1:0]   best_prio
);
  integer i;

  always @(*) begin
    best_valid = 1'b0;
    best_idx   = {($clog2(N)){1'b0}};
    best_prio  = {PRIO_BITS{1'b0}};

    for (i = 0; i < N; i = i + 1) begin
      if (eligible[i] &&
          (prio_flat[i*PRIO_BITS +: PRIO_BITS] != {PRIO_BITS{1'b0}}) &&
          (!best_valid ||
           (prio_flat[i*PRIO_BITS +: PRIO_BITS] > best_prio))) begin
        best_valid = 1'b1;
        best_idx   = i;
        best_prio  = prio_flat[i*PRIO_BITS +: PRIO_BITS];
