  localparam A_ENABLE    = 8'h04;
  localparam A_TRIGGER   = 8'h08;
  localparam A_PENDING   = 8'h0C;
  localparam A_FORCE     = 8'h10;
  localparam A_THRESH    = 8'h14;
  localparam A_CLAIM     = 8'h18;
  localparam A_INSERVICE = 8'h1C;
