  localparam A_THRESH    = 8'h14;
  localparam A_CLAIM     = 8'h18;
  localparam A_INSERVICE = 8'h1C;
  localparam A_STATUS    = 8'h20;
  localparam A_ID        = 8'h24;
  localparam A_PRIO0     = 8'h40;
  localparam PRIO_WORDS  = (NUM_SRC + 7) / 8;
  localparam [31:0] ID_VALUE = 32'h1C0D0000 | (PRIO_BITS << 8) | NUM_SRC;

  reg mapped, read_only;
  integer j;

  wire       is_prio   = (addr >= A_PRIO0) &&
                         (addr < A_PRIO0 + 4 * PRIO_WORDS);
  wire [7:0] prio_word = (addr - A_PRIO0) >> 2;

  always @(*) begin
    mapped    = is_prio;
    read_only = 1'b0;

    case (addr)
      A_CTRL, A_ENABLE, A_TRIGGER, A_PENDING, A_FORCE, A_THRESH, A_CLAIM:
        mapped = 1'b1;

      A_INSERVICE, A_STATUS, A_ID: begin
        mapped    = 1'b1;
        read_only = 1'b1;
      end

      default: ;
    endcase
  end

  assign err = (addr[1:0] != 2'b00) || !mapped || (wr_en && read_only);

  wire do_write = wr_en && !err;
  wire claim    = rd_en && !err && (addr == A_CLAIM) && irq;

  assign clear_mask =
      (do_write && (addr == A_PENDING) ? wdata[NUM_SRC-1:0] :
       {NUM_SRC{1'b0}})
    | (claim ? ({{(NUM_SRC-1){1'b0}}, 1'b1} << (irq_id - 1)) :
       {NUM_SRC{1'b0}});

  assign force_mask =
      (do_write && (addr == A_FORCE)) ?
      wdata[NUM_SRC-1:0] : {NUM_SRC{1'b0}};

  always @(*) begin
    rdata = 32'b0;

    case (addr)
      A_CTRL:
        rdata[0] = gen;

      A_ENABLE:
        rdata[NUM_SRC-1:0] = enable;

      A_TRIGGER:
        rdata[NUM_SRC-1:0] = trigger;

      A_PENDING:
        rdata[NUM_SRC-1:0] = pending;

      A_THRESH:
        rdata[PRIO_BITS-1:0] = threshold;

      A_CLAIM:
        rdata = irq ? irq_id : 32'b0;

      A_INSERVICE:
        rdata[NUM_SRC-1:0] = in_service;

      A_STATUS: begin
        rdata[0]    = irq;
        rdata[15:8] = irq ? irq_id : 8'b0;
      end

      A_ID:
        rdata = ID_VALUE;

      default: begin
        if (is_prio) begin
          for (j = 0; j < 8; j = j + 1) begin
            if (prio_word * 8 + j < NUM_SRC)
              rdata[4*j +: PRIO_BITS] =
                prio_flat[(prio_word*8 + j)*PRIO_BITS +: PRIO_BITS];
