      A_CTRL, A_ENABLE, A_TRIGGER, A_PENDING, A_FORCE, A_THRESH, A_CLAIM:
        mapped = 1'b1;

      A_INSERVICE, A_STATUS, A_ID: begin
        mapped    = 1'b1;
        read_only = 1'b1;
      end

      default: ;
    endcase
  end

  assign err = (addr[1:0] != 2'b00) || !mapped || (wr_en && read_only);

  wire do_write = wr_en && !err;
  wire claim    = rd_en && !err && (addr == A_CLAIM) && irq;

  assign clear_mask =
        ((do_write && (addr == A_PENDING))
          ? wdata[NUM_SRC-1:0]
          : {NUM_SRC{1'b0}})
      | (claim
          ? ({{(NUM_SRC-1){1'b0}}, 1'b1} << (irq_id - 1))
          : {NUM_SRC{1'b0}});

  assign force_mask =
        (do_write && (addr == A_FORCE))
          ? wdata[NUM_SRC-1:0]
          : {NUM_SRC{1'b0}};

  always @(*) begin
    rdata = 32'b0;

    case (addr)
      A_CTRL:
        rdata[0] = gen;

      A_ENABLE:
        rdata[NUM_SRC-1:0] = enable;

      A_TRIGGER:
        rdata[NUM_SRC-1:0] = trigger;

      A_PENDING:
        rdata[NUM_SRC-1:0] = pending;

      A_THRESH:
        rdata[PRIO_BITS-1:0] = threshold;

      A_CLAIM:
        rdata = irq ? irq_id : 32'b0;

      A_INSERVICE:
        rdata[NUM_SRC-1:0] = in_service;

      A_STATUS: begin
        rdata[0]    = irq;
        rdata[15:8] = irq ? irq_id : 8'b0;
      end

      A_ID:
        rdata = ID_VALUE;

      default: begin
        if (is_prio) begin
          for (j = 0; j < 8; j = j + 1) begin
            if (prio_word * 8 + j < NUM_SRC)
              rdata[4*j +: PRIO_BITS] =
                prio_flat[(prio_word * 8 + j) * PRIO_BITS +: PRIO_BITS];
          end
        end
      end
    endcase
  end

  always @(posedge clk) begin
    if (rst) begin
      gen        <= 1'b0;
      enable     <= 0;
      trigger    <= 0;
      in_service <= 0;
      threshold  <= 0;
      prio_flat  <= 0;
    end else begin
      if (claim)
        in_service[irq_id - 1] <= 1'b1;

      if (do_write) begin
        case (addr)
          A_CTRL:
            gen <= wdata[0];

          A_ENABLE:
            enable <= wdata[NUM_SRC-1:0];

          A_TRIGGER:
            trigger <= wdata[NUM_SRC-1:0];

          A_THRESH:
            threshold <= wdata[PRIO_BITS-1:0];

          A_CLAIM:
            if ((wdata >= 1) && (wdata <= NUM_SRC))
              in_service[wdata - 1] <= 1'b0;

          default: begin
            if (is_prio) begin
              for (j = 0; j < 8; j = j + 1) begin
                if (prio_word * 8 + j < NUM_SRC)
                  prio_flat[(prio_word * 8 + j) * PRIO_BITS +: PRIO_BITS]
                    <= wdata[4*j +: PRIO_BITS];
              end
            end
          end
        endcase
      end
    end
  end
endmodule


