  assign force_mask = (do_write && addr == A_FORCE) ? wdata[NUM_SRC-1:0] : {NUM_SRC{1'b0}};

  always @(*) begin
    rdata = 32'b0;
    case (addr)
      A_CTRL:      rdata[0] = gen;
      A_ENABLE:    rdata[NUM_SRC-1:0] = enable;
      A_TRIGGER:   rdata[NUM_SRC-1:0] = trigger;
      A_PENDING:   rdata[NUM_SRC-1:0] = pending;
