    if (rst) begin
      gen        <= 1'b0;
      enable     <= 0;
      trigger    <= 0;
      in_service <= 0;
      threshold  <= 0;
      prio_flat  <= 0;
    end else begin
      if (claim)
        in_service[irq_id - 1] <= 1'b1;
      if (do_write) begin
        case (addr)
          A_CTRL:    gen       <= wdata[0];
          A_ENABLE:  enable    <= wdata[NUM_SRC-1:0];
          A_TRIGGER: trigger   <= wdata[NUM_SRC-1:0];
          A_THRESH:  threshold <= wdata[PRIO_BITS-1:0];
          A_CLAIM:
            if (wdata >= 1 && wdata <= NUM_SRC)
              in_service[wdata - 1] <= 1'b0;
