  output reg [NUM_SRC-1:0]           trigger,
  output reg [NUM_SRC-1:0]           in_service,
  output reg [PRIO_BITS-1:0]         threshold,
  output reg [NUM_SRC*PRIO_BITS-1:0] prio_flat,
  output     [NUM_SRC-1:0]           clear_mask,
  output     [NUM_SRC-1:0]           force_mask
