                         (addr < A_PRIO0 + 4 * PRIO_WORDS);
  wire [7:0] prio_word = (addr - A_PRIO0) >> 2;

  always @(*) begin
    mapped    = is_prio;
    read_only = 1'b0;
    case (addr)
      A_CTRL, A_ENABLE, A_TRIGGER, A_PENDING, A_FORCE, A_THRESH, A_CLAIM:
        mapped = 1'b1;
      A_INSERVICE, A_STATUS, A_ID: begin
        mapped    = 1'b1;
        read_only = 1'b1;
      end
      default: ;
