module intc_sync #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] d,
  output reg [N-1:0] q
);
  reg [N-1:0] sync_ff1;

  always @(posedge clk) begin
    if (rst) begin
      sync_ff1 <= {N{1'b0}};
      q        <= {N{1'b0}};
    end
    else begin
      sync_ff1 <= d;
      q        <= sync_ff1;
