module intc_pending #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] src,
  input      [N-1:0] trigger,
  input      [N-1:0] clear_mask,
  input      [N-1:0] force_mask,
  output reg [N-1:0] pending
);
  reg [N-1:0] src_prev;
  wire [N-1:0] set_mask;

  assign set_mask =
      ((~trigger) & src) |
      (trigger & src & ~src_prev) |
      force_mask;

  always @(posedge clk) begin
    if (rst) begin
      pending  <= {N{1'b0}};
      src_prev <= {N{1'b0}};
