  wire do_write = wr_en && !err;
  wire claim    = rd_en && !err && (addr == A_CLAIM) && irq;

  assign clear_mask = (do_write && addr == A_PENDING
                       ? wdata[NUM_SRC-1:0]
                       : {NUM_SRC{1'b0}})
