  always @(*) begin
    rdata = 32'b0;
    case (addr)
      A_CTRL:      rdata[0] = gen;
      A_ENABLE:    rdata[NUM_SRC-1:0] = enable;
      A_TRIGGER:   rdata[NUM_SRC-1:0] = trigger;
      A_PENDING:   rdata[NUM_SRC-1:0] = pending;
      A_THRESH:    rdata[PRIO_BITS-1:0] = threshold;
      A_CLAIM:     rdata = irq ? irq_id : 32'b0;
