  reg mapped, read_only;
  integer j;

  wire       is_prio   = (addr >= A_PRIO0) &&
                         (addr < A_PRIO0 + 4 * PRIO_WORDS);
  wire [7:0] prio_word = (addr - A_PRIO0) >> 2;

  always @(*) begin
    mapped    = is_prio;
    read_only = 1'b0;

