               !mapped ||
               (wr_en && read_only);

  wire do_write = wr_en && !err;
  wire claim    = rd_en && !err && (addr == A_CLAIM) && irq;

  assign clear_mask =
       (do_write && (addr == A_PENDING))
         ? wdata[NUM_SRC-1:0]
         : {NUM_SRC{1'b0}}
     | (claim
         ? ({{(NUM_SRC-1){1'b0}}, 1'b1} << (irq_id - 1))
         : {NUM_SRC{1'b0}});

  assign force_mask =
       (do_write && (addr == A_FORCE))
         ? wdata[NUM_SRC-1:0]
         : {NUM_SRC{1'b0}};

  always @(*) begin
    rdata = 32'b0;

    case (addr)
      A_CTRL:
        rdata[0] = gen;

      A_ENABLE:
        rdata[NUM_SRC-1:0] = enable;

      A_TRIGGER:
        rdata[NUM_SRC-1:0] = trigger;

      A_PENDING:
        rdata[NUM_SRC-1:0] = pending;

      A_THRESH:
        rdata[PRIO_BITS-1:0] = threshold;

      A_CLAIM:
        rdata = irq ? irq_id : 32'b0;

      A_INSERVICE:
        rdata[NUM_SRC-1:0] = in_service;

      A_STATUS: begin
        rdata[0]    = irq;
        rdata[15:8] = irq ? irq_id : 8'b0;
