  always @(posedge clk) begin
    if (rst) begin
      gen        <= 1'b0;
      enable     <= 0;
      trigger    <= 0;
      in_service <= 0;
      threshold  <= 0;
      prio_flat  <= 0;
    end else begin
      if (claim) begin
        in_service[irq_id - 1] <= 1'b1;
      end else if (do_write) begin
        case (addr)
          A_CTRL:
            gen <= wdata[0];

          A_ENABLE:
            enable <= wdata[NUM_SRC-1:0];

