      A_ID:        rdata = ID_VALUE;
      default:
        if (is_prio)
          for (j = 0; j < 8; j = j + 1)
            if (prio_word * 8 + j < NUM_SRC)
              rdata[4*j +: PRIO_BITS] = prio_flat[(prio_word*8 + j)*PRIO_BITS +: PRIO_BITS];
    endcase
  end

  wire complete = do_write &&
                  (addr == A_CLAIM) &&
                  (wdata >= 32'd1) &&
                  (wdata <= NUM_SRC);

  always @(posedge clk) begin
    if (rst) begin
      gen        <= 1'b0;
      enable     <= {NUM_SRC{1'b0}};
      trigger    <= {NUM_SRC{1'b0}};
      in_service <= {NUM_SRC{1'b0}};
      threshold  <= {PRIO_BITS{1'b0}};
