            threshold <= wdata[PRIO_BITS-1:0];

          A_CLAIM:
            if ((wdata >= 1) && (wdata <= NUM_SRC))
              in_service[wdata - 1] <= 1'b0;

          default:
            if (is_prio)
              for (j = 0; j < 8; j = j + 1)
                if (prio_word * 8 + j < NUM_SRC)
                  prio_flat[(prio_word*8 + j)*PRIO_BITS +: PRIO_BITS]
                    <= wdata[4*j +: PRIO_BITS];
        endcase
      end
    end
  end
endmodule


module apb_intc #(
  parameter NUM_SRC   = 8,
  parameter PRIO_BITS = 3
) (
  input                              PCLK,
  input                              PRESETn,
  input                              PSEL,
  input                              PENABLE,
  input                              PWRITE,
  input  [7:0]                       PADDR,
  input  [31:0]                      PWDATA,
  output [31:0]                      PRDATA,
  output                             PREADY,
  output                             PSLVERR,
  input  [NUM_SRC-1:0]               irq_src,
  output                             irq,
  output [$clog2(NUM_SRC+1)-1:0]     irq_id
);
  localparam IDW = $clog2(NUM_SRC + 1);

  wire                     rst = !PRESETn;
  wire                     wr_en, rd_en, err;
  wire [7:0]               addr;
  wire [31:0]              wdata, rdata;
  wire                     gen;
  wire [NUM_SRC-1:0]       enable, trigger, in_service, pending;
  wire [NUM_SRC-1:0]       src_sync, clear_mask, force_mask;
  wire [PRIO_BITS-1:0]     threshold, best_prio;
  wire [NUM_SRC*PRIO_BITS-1:0] prio_flat;
  wire                     best_valid;
  wire [$clog2(NUM_SRC)-1:0] best_idx;

  wire eligible_any = best_valid && gen && (best_prio > threshold);
  wire [NUM_SRC-1:0] eligible = pending & enable & ~in_service;

  assign irq    = eligible_any;
  assign irq_id = irq ? best_idx + 1 : {IDW{1'b0}};

  intc_apb_if u_apb (
    .PSEL(PSEL && PRESETn),
    .PENABLE(PENABLE),
    .PWRITE(PWRITE),
    .PADDR(PADDR),
    .PWDATA(PWDATA),
    .PRDATA(PRDATA),
    .PREADY(PREADY),
    .PSLVERR(PSLVERR),
    .wr_en(wr_en),
    .rd_en(rd_en),
    .addr(addr),
    .wdata(wdata),
    .rdata(rdata),
    .err(err)
  );

  intc_sync #(.N(NUM_SRC)) u_sync (
    .clk(PCLK),
    .rst(rst),
    .d(irq_src),
    .q(src_sync)
  );

  intc_pending #(.N(NUM_SRC)) u_pending (
    .clk(PCLK),
    .rst(rst),
    .src(src_sync),
    .trigger(trigger),
    .clear_mask(clear_mask),
    .force_mask(force_mask),
    .pending(pending)
  );

  intc_prio_select #(.N(NUM_SRC), .PRIO_BITS(PRIO_BITS)) u_select (
    .eligible(eligible),
    .prio_flat(prio_flat),
    .best_valid(best_valid),
    .best_idx(best_idx),
    .best_prio(best_prio)
  );

  intc_regs #(.NUM_SRC(NUM_SRC), .PRIO_BITS(PRIO_BITS)) u_regs (
    .clk(PCLK),
    .rst(rst),
    .wr_en(wr_en),
    .rd_en(rd_en),
    .addr(addr),
    .wdata(wdata),
    .rdata(rdata),
    .err(err),
    .pending(pending),
    .irq(irq),
    .irq_id(irq_id),
    .gen(gen),
    .enable(enable),
    .trigger(trigger),
    .in_service(in_service),
    .threshold(threshold),
    .prio_flat(prio_flat),
    .clear_mask(clear_mask),
    .force_mask(force_mask)
  );
endmodule
